  1|-- ===========================================================================
  2|-- 00_bootstrap / 02_roles_grants.sql
  3|-- ===========================================================================
  4|-- Role hierarchy and grants.
  5|--
  6|-- Requires a role that can create roles (ACCOUNTADMIN or a delegate). If the
  7|-- deploying principal cannot, this file fails first and nothing else is
  8|-- half-created.
  9|--
 10|-- Design note on least privilege: the branch analyst roles get SELECT only.
 11|-- They are the subjects of the row-access-policy demo, so granting them write
 12|-- access anywhere would undermine the very claim being demonstrated.
 13|-- ===========================================================================
 14|
 15|USE ROLE ACCOUNTADMIN;
 16|
 17|-- --------------------------------------------------------------------------
 18|-- Roles
 19|-- --------------------------------------------------------------------------
 20|CREATE ROLE IF NOT EXISTS {{ role.admin }}
 21|    COMMENT = 'Owns all Risk Copilot objects ({{ profile }}).';
 22|
 23|CREATE ROLE IF NOT EXISTS {{ role.service }}
 24|    COMMENT = 'Used by Cortex agents and scheduled automations. Never a human.';
 25|
 26|CREATE ROLE IF NOT EXISTS {{ role.compliance_officer }}
 27|    COMMENT = 'Sees all data; the only role permitted to attest an artifact.';
 28|
 29|{% for region, analyst_role in role.branch_analysts.items() %}
 30|CREATE ROLE IF NOT EXISTS {{ analyst_role }}
 31|    COMMENT = 'Branch analyst restricted to branch_region = {{ region }} by row access policy.';
 32|{% endfor %}
 33|
 34|-- --------------------------------------------------------------------------
 35|-- Hierarchy.  Inheritance runs upward: ACCOUNTADMIN sees everything
 36|-- {{ role.admin }} can see, which is what keeps the account auditable.
 37|-- --------------------------------------------------------------------------
 38|GRANT ROLE {{ role.admin }} TO ROLE ACCOUNTADMIN;
 39|GRANT ROLE {{ role.service }} TO ROLE {{ role.admin }};
 40|GRANT ROLE {{ role.compliance_officer }} TO ROLE {{ role.admin }};
 41|{% for region, analyst_role in role.branch_analysts.items() %}
 42|GRANT ROLE {{ analyst_role }} TO ROLE {{ role.admin }};
 43|{% endfor %}
 44|
 45|-- The deploying user needs the admin role to apply every later stage.
 46|-- GRANT ROLE ... TO USER takes a literal identifier and rejects IDENTIFIER(),
 47|-- so the user name is resolved at run time and the grant issued as dynamic SQL.
 48|-- Quoted, because a user name is not guaranteed to be a bare identifier.
 49|EXECUTE IMMEDIATE $$
 50|BEGIN
 51|    LET deploying_user STRING := CURRENT_USER();
 52|    EXECUTE IMMEDIATE 'GRANT ROLE {{ role.admin }} TO USER "' || deploying_user || '"';
 53|    RETURN 'granted {{ role.admin }} to ' || deploying_user;
 54|END;
 55|$$;
 56|
 57|-- --------------------------------------------------------------------------
 58|-- Warehouse privileges
 59|-- --------------------------------------------------------------------------
 60|GRANT USAGE ON WAREHOUSE {{ wh.dev }} TO ROLE {{ role.admin }};
 61|GRANT OPERATE, USAGE ON WAREHOUSE {{ wh.pipeline }} TO ROLE {{ role.admin }};
 62|GRANT USAGE ON WAREHOUSE {{ wh.pipeline }} TO ROLE {{ role.service }};
 63|GRANT USAGE ON WAREHOUSE {{ wh.demo }} TO ROLE {{ role.service }};
 64|GRANT USAGE ON WAREHOUSE {{ wh.demo }} TO ROLE {{ role.compliance_officer }};
 65|{% for region, analyst_role in role.branch_analysts.items() %}
 66|GRANT USAGE ON WAREHOUSE {{ wh.demo }} TO ROLE {{ analyst_role }};
 67|{% endfor %}
 68|
 69|-- --------------------------------------------------------------------------
 70|-- Ownership.  The admin role owns everything, so object ownership does not
 71|-- follow whichever human happened to run the deploy.
 72|-- --------------------------------------------------------------------------
 73|GRANT OWNERSHIP ON DATABASE {{ db }} TO ROLE {{ role.admin }} COPY CURRENT GRANTS;
 74|{% for key in ['raw', 'curated', 'governance', 'evidence', 'audit', 'ground_truth', 'ml'] %}
 75|GRANT OWNERSHIP ON SCHEMA {{ fq[key] }} TO ROLE {{ role.admin }} COPY CURRENT GRANTS;
 76|{% endfor %}
 77|
 78|USE ROLE {{ role.admin }};
 79|
 80|-- --------------------------------------------------------------------------
 81|-- Database and schema usage
 82|-- --------------------------------------------------------------------------
 83|{% set consumer_roles = [role.service, role.compliance_officer] + role.branch_analysts.values()|list %}
 84|{% for consumer in consumer_roles %}
 85|GRANT USAGE ON DATABASE {{ db }} TO ROLE {{ consumer }};
 86|GRANT USAGE ON SCHEMA {{ fq.curated }} TO ROLE {{ consumer }};
 87|GRANT USAGE ON SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
 88|GRANT USAGE ON SCHEMA {{ fq.evidence }} TO ROLE {{ consumer }};
 89|{% endfor %}
 90|
 91|-- --------------------------------------------------------------------------
 92|-- Read access to curated and governance state.
 93|--
 94|-- FUTURE GRANTS cover objects created by later stages, so a new dynamic table
 95|-- does not silently become invisible to the roles that need it. They apply only
 96|-- to objects created AFTER the grant, so the matching ALL GRANTS below covers
 97|-- anything that already exists on a re-run.
 98|-- --------------------------------------------------------------------------
 99|{% for consumer in consumer_roles %}
100|GRANT SELECT ON FUTURE TABLES         IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
101|GRANT SELECT ON FUTURE VIEWS          IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
102|GRANT SELECT ON FUTURE DYNAMIC TABLES IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
103|GRANT SELECT ON FUTURE TABLES         IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
104|GRANT SELECT ON FUTURE VIEWS          IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
105|GRANT SELECT ON ALL TABLES            IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
106|GRANT SELECT ON ALL VIEWS             IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
107|GRANT SELECT ON ALL DYNAMIC TABLES    IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
108|GRANT SELECT ON ALL TABLES            IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
109|GRANT SELECT ON ALL VIEWS             IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
110|{% endfor %}
111|
112|-- --------------------------------------------------------------------------
113|-- Evidence chain.
114|--
115|-- Read for everyone who investigates; write ONLY for the service role, because
116|-- the chain is append-only and must be written by the pipeline rather than by
117|-- hand. Analysts deliberately get no INSERT: a human editing an evidence row
118|-- would destroy the reproducibility claim.
119|-- --------------------------------------------------------------------------
120|{% for consumer in consumer_roles %}
121|GRANT SELECT ON FUTURE TABLES IN SCHEMA {{ fq.evidence }} TO ROLE {{ consumer }};
122|GRANT SELECT ON ALL TABLES    IN SCHEMA {{ fq.evidence }} TO ROLE {{ consumer }};
123|{% endfor %}
124|
125|GRANT INSERT, UPDATE ON FUTURE TABLES IN SCHEMA {{ fq.evidence }} TO ROLE {{ role.service }};
126|GRANT INSERT, UPDATE ON ALL TABLES    IN SCHEMA {{ fq.evidence }} TO ROLE {{ role.service }};
127|
128|-- The Principal Officer's attestation is the human gate on filing. Only the
129|-- compliance role may write one; this is the maker-checker boundary expressed
130|-- as a privilege rather than as prose in a prompt.
131|GRANT USAGE ON SCHEMA {{ fq.audit }} TO ROLE {{ role.service }};
132|GRANT INSERT ON FUTURE TABLES IN SCHEMA {{ fq.audit }} TO ROLE {{ role.service }};
133|GRANT INSERT ON ALL TABLES    IN SCHEMA {{ fq.audit }} TO ROLE {{ role.service }};
134|
135|-- Compliance may read the audit trail; nobody may update or delete it.
136|GRANT USAGE ON SCHEMA {{ fq.audit }} TO ROLE {{ role.compliance_officer }};
137|GRANT SELECT ON FUTURE TABLES IN SCHEMA {{ fq.audit }} TO ROLE {{ role.compliance_officer }};
138|GRANT SELECT ON ALL TABLES    IN SCHEMA {{ fq.audit }} TO ROLE {{ role.compliance_officer }};
139|
140|-- --------------------------------------------------------------------------
141|-- GROUND_TRUTH is granted to NOBODY beyond the admin role.
142|--
143|-- This is the structural half of the label-leakage control (validation gate
144|-- V6): the agent's service role has no USAGE on the schema, so no amount of
145|-- prompt engineering can reach a label. The semantic-view check is the second
146|-- half. Enforced here rather than trusted to a YAML omission.
147|-- --------------------------------------------------------------------------
148|REVOKE ALL PRIVILEGES ON SCHEMA {{ fq.ground_truth }} FROM ROLE {{ role.service }};
149|
150|-- --------------------------------------------------------------------------
151|-- Stages
152|-- --------------------------------------------------------------------------
153|GRANT READ ON STAGE {{ fq.governance }}.{{ stage.policy_docs }} TO ROLE {{ role.service }};
154|GRANT USAGE ON SCHEMA {{ fq.ml }} TO ROLE {{ role.service }};
155|GRANT SELECT ON FUTURE TABLES IN SCHEMA {{ fq.ml }} TO ROLE {{ role.service }};
156|GRANT SELECT ON ALL TABLES    IN SCHEMA {{ fq.ml }} TO ROLE {{ role.service }};
157|

