def _is_in(values: Any, members: Iterable[Any], type_: pa.DataType) -> Any:
    return pc.fill_null(pc.is_in(values, value_set=pa.array(sorted(members), type=type_)), False)


def leg_count(pairs: pa.Table, routed_formats: frozenset[str]) -> int:
    """Legs ``pairs`` become: two each, four for a pair posted via the cash desk (D27)."""
    routed = pc.sum(_is_in(pairs["payment_format"], routed_formats, pa.string())).as_py()
    return 2 * pairs.num_rows + 2 * int(routed or 0)

stats["pairs_before_leg_cut"] = kept.num_rows
